var DATA = {"a": "USB-C plug", "b": "USB-C receptacle", "checks": "pins==24|voltage<=20|current<=5", "verdict": "compatible", "specs": "pins=24|voltage=20|current=5"};
console.log("Interface A: " + DATA.a);
console.log("Interface B: " + DATA.b);
var specs = {};
DATA.specs.split("|").forEach(function (kv) {
  var p = kv.split("=").map(function (s) { return s.trim(); });
  if (p.length === 2) specs[p[0]] = p[1];
});
var fails = 0;
DATA.checks.split("|").forEach(function (c) {
  c = c.trim();
  var m = c.match(/([\w-]+)\s*(==|<=|>=|<|>)\s*([-\w.]+)/);
  var ok = true, detail = "";
  if (m) {
    var key = m[1], op = m[2], want = m[3], got = specs[key];
    if (got === undefined) { ok = false; detail = "no data for " + key; }
    else {
      var gn = parseFloat(got), wn = parseFloat(want);
      if (!isNaN(gn) && !isNaN(wn)) {
        ok = op === "==" ? gn === wn : op === "<=" ? gn <= wn : op === ">=" ? gn >= wn : op === "<" ? gn < wn : gn > wn;
        detail = key + "=" + got + " " + op + " " + want;
      } else { ok = String(got) === want; detail = key + "=" + got + " vs " + want; }
    }
  }
  if (!ok) fails++;
  console.log("  [" + (ok ? "PASS" : "FAIL") + "] " + c + (detail ? " (" + detail + ")" : ""));
});
console.log("Expected verdict: " + DATA.verdict);
console.log("RESULT: " + (fails === 0 ? "COMPATIBLE" : fails + " check(s) FAILED — INCOMPATIBLE") + ".");

